/**
 * Plans disjoint logical key ranges using bounded seeks into persisted adjacency directories, pages, and deltas. The
 * caller holds the transaction's native read barrier for the complete call. No statement cursor or full-store
 * cardinality pass is opened: each sample inspects bounded pages, and sparse residual filters may decline a split.
 */
final class LmdbAdjacencyRangePlanner {

	private static final int MAX_PARTITIONS = 256;
	private static final int EDGE_KEY_BYTES = 33;
	private static final int ROW_PREFIX_BYTES = 17;
	private static final int PARTITION_PREFIX_BYTES = 9;
	private static final int PAGE_CACHE_SIZE = 8;
	private final LmdbPersistentAdjacency adjacency;

	record Split(long[] quad, boolean startsWithContinuation) {
		Split {
			quad = quad.clone();
		}

		@Override
		public long[] quad() {
			return quad.clone();
		}
	}

	LmdbAdjacencyRangePlanner(LmdbPersistentAdjacency adjacency) {
		this.adjacency = adjacency;
	}

	List<Split> plan(long txn, String logicalOrder, long subject, long predicate, long object, long context,
			boolean explicit, int targetPartitions, int tupleLength) throws IOException {
		if (tupleLength < 1 || tupleLength > 4) {
			throw new IllegalArgumentException("Split tuple length must be between one and four");
		}
		int[] order = switch (logicalOrder) {
		case "psoc" -> new int[] { 1, 0, 2, 3 };
		case "posc" -> new int[] { 1, 2, 0, 3 };
		case "spoc" -> new int[] { 0, 1, 2, 3 };
		case "opsc" -> new int[] { 2, 1, 0, 3 };
		default -> null;
		};
		if (order == null || targetPartitions <= 1) {
			return List.of();
		}
		int partitions = Math.min(targetPartitions, MAX_PARTITIONS);
		Budget budget = new Budget(partitions);
		try (Cursor directories = new Cursor(txn, adjacency.metadataDbi(), budget);
				Cursor pages = new Cursor(txn, adjacency.pagesDbi(), budget);
				Cursor deltas = new Cursor(txn, adjacency.deltasDbi(), budget)) {
			return new Search(txn, order, new long[] { subject, predicate, object, context }, explicit,
					budget, directories, pages, deltas).plan(partitions, tupleLength);
		}
	}

	private record Interval(long[] first, long[] last) {
	}

	private record PageFence(int plane, long predicate, long row, long neighbor, long context) {
	}

	private final class Search {
		private final long txn;
		private final int[] order;
		private final long[] pattern;
		private final int plane;
		private final int rowComponent;
		private final int neighborComponent;
		private final byte directoryType;
		private final Budget budget;
		private final Cursor directories;
		private final Cursor pages;
		private final Cursor deltas;
		private final LinkedHashMap<PageFence, DecodedPage> decodedPages = new LinkedHashMap<>(16, 0.75f, true);

		Search(long txn, int[] order, long[] pattern, boolean explicit, Budget budget,
				Cursor directories, Cursor pages, Cursor deltas) {
			this.txn = txn;
			this.order = order;
			this.pattern = pattern;
			boolean incoming = order[0] == 2 || order[1] == 2;
			plane = (explicit ? 0 : 2) + (incoming ? 1 : 0);
			rowComponent = incoming ? 2 : 0;
			neighborComponent = incoming ? 0 : 2;
			directoryType = order[0] == 1 ? (byte) 3 : (byte) 4;
			this.budget = budget;
			this.directories = directories;
			this.pages = pages;
			this.deltas = deltas;
		}

		List<Split> plan(int partitions, int tupleLength) throws IOException {
			List<Split> splits = new ArrayList<>(partitions - 1);
			try {
				long[] first = seek(extreme(true), true);
				long[] last = seek(extreme(false), false);
				if (first == null || last == null || compare(first, last, tupleLength) >= 0) {
					return List.of();
				}
				ArrayDeque<Interval> intervals = new ArrayDeque<>();
				intervals.add(new Interval(first, last));
				while (splits.size() < partitions - 1 && !intervals.isEmpty()) {
					Interval interval = intervals.removeFirst();
					long[] midpoint = midpoint(interval.first(), interval.last(), tupleLength);
					long[] candidate = seek(midpoint, true);
					if (candidate == null || compare(candidate, interval.first(), tupleLength) <= 0
							|| compare(candidate, interval.last(), tupleLength) > 0) {
						continue;
					}
					long[] before = stepPrefix(candidate, tupleLength, false);
					long[] predecessor = before == null ? null : seek(before, false);
					if (predecessor == null || compare(predecessor, interval.first(), tupleLength) < 0) {
						continue;
					}
					boolean continuation = candidate[1] == predecessor[1]
							&& candidate[rowComponent] == predecessor[rowComponent];
					splits.add(new Split(candidate, continuation));
					// Breadth-first subdivision gives a dense cluster its own refinements even when the other
					// half of the key domain contains only a few distant values.
					if (compare(interval.first(), predecessor, tupleLength) < 0) {
						intervals.addLast(new Interval(interval.first(), predecessor));
					}
					if (compare(candidate, interval.last(), tupleLength) < 0) {
						intervals.addLast(new Interval(candidate, interval.last()));
					}
				}
			} catch (ProbeLimitReached ignored) {
				// Every already accepted boundary has a matching tuple on each side. Keeping those boundaries
				// remains exact; the caller simply obtains fewer workers for a sparse or difficult range.
			}
			splits.sort((left, right) -> compare(left.quad, right.quad, tupleLength));
			return List.copyOf(splits);
		}

		private long[] midpoint(long[] first, long[] last, int tupleLength) {
			ByteBuffer low = ByteBuffer.allocate(tupleLength * Long.BYTES);
			ByteBuffer high = ByteBuffer.allocate(tupleLength * Long.BYTES);
			for (int i = 0; i < tupleLength; i++) {
				low.putLong(first[order[i]]);
				high.putLong(last[order[i]]);
			}
			byte[] midpoint = new BigInteger(1, low.array()).add(new BigInteger(1, high.array()))
					.add(BigInteger.ONE)
					.shiftRight(1)
					.toByteArray();
			byte[] fixed = new byte[tupleLength * Long.BYTES];
			int copied = Math.min(fixed.length, midpoint.length);
			System.arraycopy(midpoint, midpoint.length - copied, fixed, fixed.length - copied, copied);
			ByteBuffer fields = ByteBuffer.wrap(fixed);
			long[] result = extreme(true);
			for (int i = 0; i < tupleLength; i++) {
				result[order[i]] = fields.getLong();
			}
			return result;
		}

		private long[] extreme(boolean forward) {
			long[] result = new long[4];
			for (int field = 0; field < result.length; field++) {
				result[field] = pattern[field] == -1 ? forward ? 0 : -1 : pattern[field];
			}
			return result;
		}

		/** Smallest/largest tuple on the requested side of a target that agrees with every fixed component. */
		private long[] alignWithPattern(long[] target, boolean forward) {
			long[] aligned = target.clone();
			for (int position = 0; position < order.length; position++) {
				int field = order[position];
				if (pattern[field] == -1 || pattern[field] == aligned[field]) {
					continue;
				}
				int comparison = Long.compareUnsigned(pattern[field], aligned[field]);
				if (forward ? comparison > 0 : comparison < 0) {
					aligned[field] = pattern[field];
					fillSuffix(aligned, position + 1, forward);
					return aligned;
				}
				for (int carry = position - 1; carry >= 0; carry--) {
					int carryField = order[carry];
					if (pattern[carryField] == -1 && aligned[carryField] != (forward ? -1L : 0L)) {
						aligned[carryField] += forward ? 1 : -1;
						fillSuffix(aligned, carry + 1, forward);
						return aligned;
					}
				}
				return null;
			}
			return aligned;
		}

		private void fillSuffix(long[] quad, int fromPosition, boolean forward) {
			for (int i = fromPosition; i < order.length; i++) {
				int field = order[i];
				quad[field] = pattern[field] == -1 ? forward ? 0 : -1 : pattern[field];
			}
		}

		private long[] stepPrefix(long[] quad, int prefixLength, boolean forward) {
			long[] target = quad.clone();
			for (int position = prefixLength - 1; position >= 0; position--) {
				int field = order[position];
				if (target[field] != (forward ? -1L : 0L)) {
					target[field] += forward ? 1 : -1;
					// This is a raw tuple predecessor/successor; alignment applies fixed pattern values later.
					for (int i = position + 1; i < order.length; i++) {
						target[order[i]] = forward ? 0 : -1;
					}
					return target;
				}
			}
			return null;
		}

		private long[] seek(long[] requested, boolean forward) throws IOException {
			long[] target = alignWithPattern(requested, forward);
			while (target != null) {
				byte[] directoryKey = ByteBuffer.allocate(18)
						.put(directoryType)
						.put((byte) plane)
						.putLong(target[order[0]])
						.putLong(target[order[1]])
						.array();
				boolean available = forward ? directories.seek(directoryKey) : directories.floor(directoryKey);
				if (!available) {
					return null;
				}
				byte[] found = directories.key();
				if (found.length < 2 || found[0] != directoryType || found[1] != plane) {
					return null;
				}
				if (found.length != 18 || directories.value().remaining() != Long.BYTES
						|| directories.value().getLong() <= 0) {
					throw new IOException("Invalid persisted adjacency directory entry while planning ranges");
				}
				long[] row = extreme(forward);
				row[order[0]] = readLong(found, 2);
				row[order[1]] = readLong(found, 10);
				long[] alignedRow = alignWithPattern(row, forward);
				if (alignedRow == null) {
					return null;
				}
				if (compare(row, alignedRow, 2) != 0) {
					target = alignedRow;
					continue;
				}
				if (compare(row, target, 2) == 0) {
					row[order[2]] = target[order[2]];
					row[order[3]] = target[order[3]];
				}
				long[] base = baseInRow(row, forward);
				long[] delta = deltaInRow(row, forward);
				if (base != null && delta != null) {
					int compared = compare(base, delta, 4);
					return (forward ? compared <= 0 : compared >= 0) ? base : delta;
				}
				if (base != null || delta != null) {
					return base != null ? base : delta;
				}
				long[] nextRow = stepPrefix(row, 2, forward);
				target = nextRow == null ? null : alignWithPattern(nextRow, forward);
			}
			return null;
		}

		private long[] baseInRow(long[] target, boolean forward) throws IOException {
			byte[] edge = edgeKey(target);
			boolean available = pages.floor(edge);
			if (!available || !hasPrefix(pages.key(), edge, PARTITION_PREFIX_BYTES)) {
				if (!forward) {
					return null;
				}
				available = pages.seek(Arrays.copyOf(edge, ROW_PREFIX_BYTES));
			}
			while (available) {
				byte[] key = pages.key();
				if (!hasPrefix(key, edge, PARTITION_PREFIX_BYTES)) {
					return null;
				}
				DecodedPage page = decode(key);
				int position = bound(page, target, !forward) - (forward ? 0 : 1);
				for (; position >= 0 && position < page.size(); position += forward ? 1 : -1) {
					int rowComparison = Long.compareUnsigned(page.rowAt(position), target[rowComponent]);
					if (rowComparison != 0) {
						if (forward ? rowComparison > 0 : rowComparison < 0) {
							return null;
						}
						continue;
					}
					long[] quad = quad(target[1], page.rowAt(position), page.neighborAt(position),
							page.contextAt(position));
					if (matches(quad) && deltaState(edgeKey(quad)) != 0) {
						return quad;
					}
				}
				available = forward ? pages.next() : pages.previous();
			}
			return null;
		}

		private long[] deltaInRow(long[] target, boolean forward) throws IOException {
			byte[] edge = edgeKey(target);
			boolean available = forward ? deltas.seek(edge) : deltas.floor(edge);
			while (available) {
				byte[] key = deltas.key();
				if (!hasPrefix(key, edge, ROW_PREFIX_BYTES)) {
					return null;
				}
				if (key.length != EDGE_KEY_BYTES) {
					throw new IOException("Invalid persisted adjacency delta key while planning ranges");
				}
				int state = LmdbAdjacencyRangePlanner.deltaState(deltas.value());
				long[] quad = quad(readLong(key, 1), readLong(key, 9), readLong(key, 17), readLong(key, 25));
				if (state == 1 && matches(quad)) {
					return quad;
				}
				available = forward ? deltas.next() : deltas.previous();
			}
			return null;
		}

		private int deltaState(byte[] key) throws IOException {
			budget.read();
			try (MemoryStack stack = MemoryStack.stackPush()) {
				MDBVal value = MDBVal.malloc(stack);
				int result = mdb_get(txn, adjacency.deltasDbi(), MDBVal.malloc(stack).mv_data(stack.bytes(key)), value);
				if (result == MDB_NOTFOUND) {
					return -1;
				}
				LmdbUtil.E(result);
				if (value.mv_size() != 1) {
					throw new IOException("Invalid persisted adjacency delta value while planning ranges");
				}
				return LmdbAdjacencyRangePlanner.deltaState(value.mv_data());
			}
		}

		private DecodedPage decode(byte[] key) throws IOException {
			if (key.length != EDGE_KEY_BYTES || key[0] != plane) {
				throw new IOException("Invalid persisted adjacency page key while planning ranges");
			}
			PageFence fence = new PageFence(plane, readLong(key, 1), readLong(key, 9), readLong(key, 17),
					readLong(key, 25));
			DecodedPage page = decodedPages.get(fence);
			if (page == null) {
				budget.page();
				try {
					page = PersistentCsfPageCodec.decode(pages.value());
				} catch (IllegalArgumentException failure) {
					throw new IOException("Malformed persisted adjacency page while planning ranges", failure);
				}
				if (page.rowAt(0) != fence.row() || page.neighborAt(0) != fence.neighbor()
						|| page.contextAt(0) != fence.context()) {
					throw new IOException("Persisted adjacency page disagrees with its fence while planning ranges");
				}
				decodedPages.put(fence, page);
				if (decodedPages.size() > PAGE_CACHE_SIZE) {
					decodedPages.remove(decodedPages.keySet().iterator().next());
				}
			}
			return page;
		}

		private int bound(DecodedPage page, long[] quad, boolean upper) {
			int low = 0;
			int high = page.size();
			while (low < high) {
				int middle = (low + high) >>> 1;
				int compared = Long.compareUnsigned(page.rowAt(middle), quad[rowComponent]);
				if (compared == 0) {
					compared = Long.compareUnsigned(page.neighborAt(middle), quad[neighborComponent]);
				}
				if (compared == 0) {
					compared = Long.compareUnsigned(page.contextAt(middle), quad[3]);
				}
				if (compared < 0 || upper && compared == 0) {
					low = middle + 1;
				} else {
					high = middle;
				}
			}
			return low;
		}

		private boolean matches(long[] quad) {
			for (int field = 0; field < quad.length; field++) {
				if (pattern[field] != -1 && pattern[field] != quad[field]) {
					return false;
				}
			}
			return true;
		}

		private long[] quad(long predicate, long row, long neighbor, long context) {
			long[] quad = new long[4];
			quad[1] = predicate;
			quad[rowComponent] = row;
			quad[neighborComponent] = neighbor;
			quad[3] = context;
			return quad;
		}

		private byte[] edgeKey(long[] quad) {
			return ByteBuffer.allocate(EDGE_KEY_BYTES)
					.put((byte) plane)
					.putLong(quad[1])
					.putLong(quad[rowComponent])
					.putLong(quad[neighborComponent])
					.putLong(quad[3])
					.array();
		}

		private int compare(long[] left, long[] right, int tupleLength) {
			for (int i = 0; i < tupleLength; i++) {
				int compared = Long.compareUnsigned(left[order[i]], right[order[i]]);
				if (compared != 0) {
					return compared;
				}
			}
			return 0;
		}
	}

	private static int deltaState(ByteBuffer value) throws IOException {
		if (value.remaining() != 1 || value.get(value.position()) < 0 || value.get(value.position()) > 1) {
			throw new IOException("Invalid persisted adjacency delta value while planning ranges");
		}
		return value.get(value.position());
	}

	private static long readLong(byte[] bytes, int offset) {
		return ByteBuffer.wrap(bytes).getLong(offset);
	}

	private static boolean hasPrefix(byte[] key, byte[] prefix, int length) {
		return key.length >= length && Arrays.mismatch(key, 0, length, prefix, 0, length) < 0;
	}

	private static final class ProbeLimitReached extends RuntimeException {
		private static final long serialVersionUID = 1L;

		ProbeLimitReached() {
			super(null, null, false, false);
		}
	}

	private static final class Budget {
		private int readsRemaining;
		private int pagesRemaining;

		Budget(int partitions) {
			readsRemaining = Math.min(32_768, Math.max(256, partitions * 128));
			pagesRemaining = Math.min(256, Math.max(16, partitions * 8));
		}

		void read() {
			if (--readsRemaining < 0) {
				throw new ProbeLimitReached();
			}
			if ((readsRemaining & 63) == 0) {
				NativeLmdbQuerySource.checkpointCancellation();
			}
		}

		void page() {
			if (--pagesRemaining < 0) {
				throw new ProbeLimitReached();
			}
		}
	}

	/** All mapped buffers are consumed before the next cursor operation; only detached keys and pages escape. */
	private static final class Cursor implements AutoCloseable {
		private final Budget budget;
		private final MDBVal key;
		private final MDBVal value;
		private final ByteBuffer seekBuffer;
		private long cursor;

		Cursor(long txn, int dbi, Budget budget) throws IOException {
			this.budget = budget;
			key = MDBVal.malloc();
			value = MDBVal.malloc();
			seekBuffer = MemoryUtil.memAlloc(EDGE_KEY_BYTES);
			try (MemoryStack stack = MemoryStack.stackPush()) {
				PointerBuffer handle = stack.mallocPointer(1);
				LmdbUtil.E(mdb_cursor_open(txn, dbi, handle));
				cursor = handle.get(0);
			} catch (IOException | RuntimeException | Error failure) {
				key.free();
				value.free();
				MemoryUtil.memFree(seekBuffer);
				throw failure;
			}
		}

		boolean seek(byte[] target) throws IOException {
			seekBuffer.clear().put(target).flip();
			key.mv_data(seekBuffer);
			return move(MDB_SET_RANGE);
		}

		boolean floor(byte[] target) throws IOException {
			if (!seek(target)) {
				return move(MDB_LAST);
			}
			return Arrays.compareUnsigned(key(), target) <= 0 || previous();
		}

		boolean next() throws IOException {
			return move(MDB_NEXT);
		}

		boolean previous() throws IOException {
			return move(MDB_PREV);
		}

		private boolean move(int operation) throws IOException {
			budget.read();
			int result = mdb_cursor_get(cursor, key, value, operation);
			if (result == MDB_NOTFOUND) {
				return false;
			}
			LmdbUtil.E(result);
			return true;
		}

		byte[] key() throws IOException {
			if (key.mv_size() < 1 || key.mv_size() > EDGE_KEY_BYTES) {
				throw new IOException("Invalid persisted adjacency key size while planning ranges");
			}
			byte[] bytes = new byte[(int) key.mv_size()];
			key.mv_data().get(bytes);
			return bytes;
		}

		ByteBuffer value() throws IOException {
			if (value.mv_size() < 1 || value.mv_size() > 128 * 1024) {
				throw new IOException("Invalid persisted adjacency value size while planning ranges");
			}
			return value.mv_data().order(ByteOrder.BIG_ENDIAN);
		}

		@Override
		public void close() {
			if (cursor != 0) {
				mdb_cursor_close(cursor);
				cursor = 0;
				key.free();
				value.free();
				MemoryUtil.memFree(seekBuffer);
			}
		}
	}
}
